   +    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
   +        match *self {
   +            Error::Io { ref err, ref path } => {
   +                write!(f, "{}: {}", path.display(), err)
   +            }
   +        }
   +    }
